#!/usr/bin/env bash
set -eo pipefail
export HOME=/root
export PATH="$HOME/.local/bin:$PATH"
cd /opt/mesocyclonic-viewer
echo '' | base64 -d > 'scripts/model/score.py'
uv run ruff check --fix scripts/model tests/test_model_dataset.py 2>&1 | tail -5
uv run ruff format scripts/model tests/test_model_dataset.py 2>&1 | tail -5
echo "=== check final ==="
uv run ruff check scripts/model tests/test_model_dataset.py && echo RUFF_OK
echo "=== emitir archivos formateados ==="
for f in scripts/model/build_dataset.py scripts/model/train.py scripts/model/score.py tests/test_model_dataset.py; do echo "===FILE:$f==="; base64 -w0 "$f"; echo ""; done
echo FORMAT_DONE
